import java.util.HashSet;
import java.util.Set;

class Shape {
    double area() { return 0; }
    static String kind() { return "shape"; }
}

class Circle extends Shape {
    final double r;
    Circle(double r) { this.r = r; }

    @Override double area() { return Math.PI * r * r; }     // real override: checked.
    static String kind() { return "circle"; }               // hides, doesn't override.

    @Override public boolean equals(Object o) {            // Object parameter: overrides.
        return o instanceof Circle c && c.r == r;
    }
    @Override public int hashCode() { return Double.hashCode(r); }
    // public boolean equals(Circle c) { ... }  // with @Override: compile error. Good.
}

public class Dispatch {
    public static void main(String[] args) {
        Shape s = new Circle(2);
        System.out.printf("%.2f%n", s.area());   // 12.57: Circle's version.
        System.out.println(Shape.kind());           // shape: static, by type named.
        Set<Shape> set = new HashSet<>();
        set.add(new Circle(1)); set.add(new Circle(1));
        System.out.println(set.size());             // 1
    }
}
